const fs = require('fs');
const path = require('path');
const candidateDirs = [
  $env.PROMPTS_DIR,
  '/files/git/prompts',
  '/git/n8n-workflows/prompts',
  '/prompts'
].filter(Boolean);

function readPrompt(fileName) {
  const tried = [];
  for (const dir of candidateDirs) {
    const filePath = path.join(dir, fileName);
    tried.push(filePath);
    if (fs.existsSync(filePath)) {
      return fs.readFileSync(filePath, 'utf8').trim();
    }
  }
  throw new Error(`Prompt file ${fileName} was not found. Tried: ${tried.join(', ')}`);
}

return $input.all().map((item) => ({
  json: {
    ...item.json,
    prompts: {
      supervisor: readPrompt('supervisor.md'),
      inbox: readPrompt('inbox-agent.md'),
      calendar: readPrompt('calendar-agent.md')
    }
  }
}));

function firstText(...values) {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
}

function header(headers, name) {
  if (!headers) return '';
  const target = name.toLowerCase();
  const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === target);
  return key ? String(headers[key]) : '';
}

function requireBearer(headers, expected, channel) {
  if (!expected) return;
  const auth = header(headers, 'authorization');
  if (auth !== 'Bearer ' + expected) {
    throw new Error(channel + ' webhook authorization failed');
  }
}

function requireTelegramSecret(headers) {
  if (!$env.TELEGRAM_WEBHOOK_SECRET_TOKEN) return;
  if (header(headers, 'x-telegram-bot-api-secret-token') !== $env.TELEGRAM_WEBHOOK_SECRET_TOKEN) {
    throw new Error('Telegram webhook secret token mismatch');
  }
}

function senderName(user) {
  return firstText(
    user?.username && '@' + user.username,
    [user?.first_name, user?.last_name].filter(Boolean).join(' '),
    user?.pushName,
    user?.senderName,
    user?.displayName
  );
}

const results = [];

for (const input of $input.all()) {
  const item = input.json || {};
  const headers = item.headers || {};
  const query = item.query || {};
  const payload = item.body && (item.headers || item.query) ? item.body : item;

  if (firstText(payload.chatInput, item.chatInput)) {
    results.push({
      json: {
        ...payload,
        chatInput: firstText(payload.chatInput, item.chatInput),
        sessionId: firstText(payload.sessionId, item.sessionId, 'n8n-chat'),
        sourceChannel: firstText(payload.sourceChannel, item.sourceChannel, 'n8n-chat')
      }
    });
    continue;
  }

  const telegramMessage = payload.message || payload.edited_message || payload.channel_post || payload.callback_query?.message;
  if (telegramMessage || payload.callback_query) {
    requireTelegramSecret(headers);
    const text = firstText(
      telegramMessage?.text,
      telegramMessage?.caption,
      payload.callback_query?.data
    );
    if (!text) continue;
    const chatId = telegramMessage?.chat?.id || payload.callback_query?.message?.chat?.id || payload.callback_query?.from?.id;
    const from = telegramMessage?.from || payload.callback_query?.from || {};
    results.push({
      json: {
        chatInput: text,
        sessionId: 'telegram:' + (chatId || from.id || payload.update_id || 'unknown'),
        sourceChannel: 'telegram',
        sourceMessageId: telegramMessage?.message_id || payload.callback_query?.id || '',
        sourceChatId: chatId || '',
        sourceSenderId: from.id || '',
        sourceSenderName: senderName(from),
        rawInput: payload
      }
    });
    continue;
  }

  if (payload.typeWebhook || payload.senderData || payload.messageData) {
    requireBearer(headers, $env.GREENAPI_WEBHOOK_TOKEN, 'GREEN-API');
    if (payload.typeWebhook && payload.typeWebhook !== 'incomingMessageReceived') continue;
    const messageData = payload.messageData || {};
    const textData = messageData.textMessageData || {};
    const extendedTextData = messageData.extendedTextMessageData || {};
    const fileData = messageData.fileMessageData || {};
    const text = firstText(
      textData.textMessage,
      extendedTextData.text,
      fileData.caption,
      messageData?.quotedMessage?.textMessage,
      messageData?.buttonMessageData?.buttonText
    );
    if (!text) continue;
    const chatId = payload.senderData?.chatId || payload.senderData?.sender || payload.chatId || 'unknown';
    results.push({
      json: {
        chatInput: text,
        sessionId: 'greenapi:' + chatId,
        sourceChannel: 'greenapi',
        sourceMessageId: payload.idMessage || '',
        sourceChatId: chatId,
        sourceSenderId: payload.senderData?.sender || '',
        sourceSenderName: firstText(payload.senderData?.senderName, payload.senderData?.chatName),
        rawInput: payload
      }
    });
    continue;
  }

  const whatsappEvents = [];
  if (payload.object === 'whatsapp_business_account' && Array.isArray(payload.entry)) {
    for (const entry of payload.entry) {
      for (const change of entry.changes || []) {
        const value = change.value || {};
        for (const message of value.messages || []) {
          whatsappEvents.push({ value, message, field: change.field });
        }
      }
    }
  } else if (Array.isArray(payload.messages)) {
    for (const message of payload.messages) {
      whatsappEvents.push({ value: payload, message, field: payload.field || 'messages' });
    }
  }

  if (whatsappEvents.length) {
    for (const event of whatsappEvents) {
      const message = event.message;
      const text = firstText(
        message.text?.body,
        message.button?.text,
        message.interactive?.button_reply?.title,
        message.interactive?.list_reply?.title
      );
      if (!text) continue;
      const contact = (event.value.contacts || []).find((candidate) => candidate.wa_id === message.from) || {};
      results.push({
        json: {
          chatInput: text,
          sessionId: 'whatsapp:' + (message.from || 'unknown'),
          sourceChannel: 'whatsapp-cloud',
          sourceMessageId: message.id || '',
          sourceChatId: message.from || '',
          sourceSenderId: message.from || '',
          sourceSenderName: firstText(contact.profile?.name, message.from),
          rawInput: payload
        }
      });
    }
    continue;
  }

  const genericText = firstText(payload.text, payload.message, payload.prompt, query.text);
  if (genericText) {
    results.push({
      json: {
        chatInput: genericText,
        sessionId: firstText(payload.sessionId, query.sessionId, 'webhook:generic'),
        sourceChannel: firstText(payload.sourceChannel, query.sourceChannel, 'webhook'),
        rawInput: payload
      }
    });
  }
}

return results;

const query = $input.first().json.query || {};
if ($env.WHATSAPP_VERIFY_TOKEN && query['hub.verify_token'] !== $env.WHATSAPP_VERIFY_TOKEN) {
  throw new Error('WhatsApp verify token mismatch');
}
return [{
  json: {
    responseText: query['hub.challenge'] || 'ok'
  }
}];
